begin;
do $curate$ declare bid uuid; begin if exists(select 1 from public.businesses where lower(name)=lower('Mountain House Handyman — Matt Disko') or regexp_replace(coalesce(phone,''),'[^0-9]','','g') ~ '5102397080$' or lower(rtrim(website,'/'))=lower(rtrim('https://www.mattdisko.com/','/'))) then raise exception 'Duplicate candidate requires review'; end if; insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Mountain House Handyman — Matt Disko','Home Services','Mountain House','','(510) 239-7080','https://www.mattdisko.com/','Independent freelance handyman; the operator explicitly states they are not a CSLB contractor or engineering consultant. Advertises small home repairs and maintenance, cabinets, screens, blinds and wall-hanging work. Submit the required website request form first; phone contact is for follow-up. The service request form lists Mountain House, Tracy, Lathrop and Manteca. Confirm scope and availability directly.','approved',true,false,null,0,'editorial_first_party','https://www.mattdisko.com/','first_party_website_desk_check',now()) returning id into bid; insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "Mountain House Handyman \u2014 Matt Disko", "city": "Mountain House", "address": "", "phone": "(510) 239-7080", "website": "https://www.mattdisko.com/", "description": "Independent freelance handyman; the operator explicitly states they are not a CSLB contractor or engineering consultant. Advertises small home repairs and maintenance, cabinets, screens, blinds and wall-hanging work. Submit the required website request form first; phone contact is for follow-up. The service request form lists Mountain House, Tracy, Lathrop and Manteca. Confirm scope and availability directly.", "tags": ["handyman", "small repairs", "home maintenance"], "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"], "note": "Browser-readable primary site confirms Mountain House base, public phone, named regional request-form option and explicit not-a-CSLB-contractor disclaimer. Residential street address omitted. No license-required trade qualification or quality endorsement."}'::jsonb,'Individually sourced relaunch addition; primary-site desk check only','https://www.mattdisko.com/'); insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://www.mattdisko.com/',array['identity','public phone','website','advertised services','advertised service area'],array['Mountain House','Tracy','Lathrop','Manteca'],array['handyman','small repairs','home maintenance'],'First-party website desk check only. No owner confirmation, credential validation, availability check or quality endorsement. Browser-readable primary site confirms Mountain House base, public phone, named regional request-form option and explicit not-a-CSLB-contractor disclaimer. Residential street address omitted. No license-required trade qualification or quality endorsement.'); end $curate$;
do $curate$ declare bid uuid; begin if exists(select 1 from public.businesses where lower(name)=lower('California Janitorial Services LLC') or regexp_replace(coalesce(phone,''),'[^0-9]','','g') ~ '9253834060$' or lower(rtrim(website,'/'))=lower(rtrim('https://www.californiacarpetservice.com/','/'))) then raise exception 'Duplicate candidate requires review'; end if; insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('California Janitorial Services LLC','Home Services','Tracy','','(925) 383-4060','https://www.californiacarpetservice.com/','Tracy-based cleaning provider advertising carpet, tile and grout, upholstery, pet odor removal and commercial janitorial services in Mountain House, Tracy, Lathrop and Manteca. Contact directly for project scope and scheduling. Recurring whole-house maid service was not established in this website check.','approved',true,false,null,0,'editorial_first_party','https://www.californiacarpetservice.com/','first_party_website_desk_check',now()) returning id into bid; insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "California Janitorial Services LLC", "city": "Tracy", "address": "", "phone": "(925) 383-4060", "website": "https://www.californiacarpetservice.com/", "description": "Tracy-based cleaning provider advertising carpet, tile and grout, upholstery, pet odor removal and commercial janitorial services in Mountain House, Tracy, Lathrop and Manteca. Contact directly for project scope and scheduling. Recurring whole-house maid service was not established in this website check.", "tags": ["carpet cleaning", "upholstery cleaning", "commercial cleaning", "tile and grout cleaning"], "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"], "note": "Browser-readable primary site confirms public phone, Tracy base and named cities. Street address omitted. Not tagged as recurring house cleaning; credentials, insurance, safety and availability claims not adopted."}'::jsonb,'Individually sourced relaunch addition; primary-site desk check only','https://www.californiacarpetservice.com/'); insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://www.californiacarpetservice.com/',array['identity','public phone','website','advertised services','advertised service area'],array['Mountain House','Tracy','Lathrop','Manteca'],array['carpet cleaning','upholstery cleaning','commercial cleaning','tile and grout cleaning'],'First-party website desk check only. No owner confirmation, credential validation, availability check or quality endorsement. Browser-readable primary site confirms public phone, Tracy base and named cities. Street address omitted. Not tagged as recurring house cleaning; credentials, insurance, safety and availability claims not adopted.'); end $curate$;
commit;
